require_once '../config.php';require_once '../includes/auth.php';require_admin();$id=(int)($_GET['id']??0);$get=$conn->prepare('SELECT * FROM events WHERE id=?');$get->bind_param('i',$id);$get->execute();$event=$get->get_result()->fetch_assoc();if(!$event){set_flash('error','Event not found.');redirect('dashboard.php');}$error='';
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$keys=['title','category','description','event_date','event_time','venue'];foreach($keys as $k)$event[$k]=trim((string)($_POST[$k]??''));$event['capacity']=(int)($_POST['capacity']??0);if(in_array('',array_map(fn($k)=>$event[$k],$keys),true)||$event['capacity']<1)$error='Complete all fields with valid values.';else{try{$s=$conn->prepare('UPDATE events SET title=?,category=?,description=?,event_date=?,event_time=?,venue=?,capacity=? WHERE id=?');$s->bind_param('ssssssii',$event['title'],$event['category'],$event['description'],$event['event_date'],$event['event_time'],$event['venue'],$event['capacity'],$id);$s->execute();set_flash('success','Event updated successfully.');redirect('dashboard.php');}catch(Throwable $e){error_log($e->getMessage());$error='Unable to update the event.';}}}
$page_title='Edit Event';$asset_prefix='../';include '../includes/header.php'; ?>
<main class="page-shell"><div class="form-page"><div><p class="eyebrow">EVENT CONFIGURATION</p><h1>Edit event</h1><p>Update the schedule or capacity.</p></div><?php if($error): ?><div class="alert error"><?= h($error) ?></div><?php endif; ?><form method="post" class="form form-card"><?= csrf_field() ?><label>Event Title<input name="title" maxlength="150" value="<?= h($event['title']) ?>" required></label><div class="form-row"><label>Category<input name="category" maxlength="80" value="<?= h($event['category']) ?>" required></label><label>Capacity<input type="number" min="1" name="capacity" value="<?= (int)$event['capacity'] ?>" required></label></div><label>Description<textarea name="description" rows="5" required><?= h($event['description']) ?></textarea></label><div class="form-row"><label>Date<input type="date" name="event_date" value="<?= h($event['event_date']) ?>" required></label><label>Time<input type="time" name="event_time" value="<?= h($event['event_time']) ?>" required></label></div><label>Venue<input name="venue" maxlength="150" value="<?= h($event['venue']) ?>" required></label><button class="primary-btn" type="submit">Save Changes</button></form></div></main><?php include '../includes/footer.php'; ?>
